// Extract message details from Slack webhook
const userId = event.body.event.user;
const messageText = event.body.event.text;
const timestamp = event.body.event.ts;
const channelId = event.body.event.channel;

return {
  userId: userId,
  messageText: messageText,
  timestamp: timestamp,
  channelId: channelId,
  eventId: event.body.event_id
};

// Remove bot mentions and trim whitespace
const cleanText = input.messageText
  .replace(/<@[A-Z0-9]+>/g, '')
  .replace(/^\s+|\s+$/g, '');

if (cleanText.length < 10) {
  throw new Error('Message too short (minimum 10 characters)');
}

return {
  ...input,
  cleanText: cleanText
};

const agentOutput = input.llm_output || '';

const extractField = (fieldName) => {
  const regex = new RegExp(`${fieldName}:\\s*(.+?)(?=\n[A-Z]+:|$)`, 'i');
  const match = agentOutput.match(regex);
  return match ? match[1].trim() : null;
};

const title = extractField('TITLE') || 'Untitled Task';
const description = extractField('DESCRIPTION') || 'No description provided';
const modules = (extractField('MODULES') || '').split(',').map(m => m.trim()).filter(m => m);
const assignee = extractField('ASSIGNEE') || 'unassigned';
const complexity = parseInt(extractField('COMPLEXITY') || '3');
const priority = extractField('PRIORITY') || 'Medium';
const hours = parseInt(extractField('HOURS') || '4');
const labels = (extractField('LABELS') || '').split(',').map(l => l.trim()).filter(l => l);

return {
  ...input,
  task: {
    title: title,
    description: description,
    modules: modules,
    assignee: assignee,
    complexity: Math.min(5, Math.max(1, complexity)),
    priority: priority,
    hours: hours,
    labels: labels
  }
};

const timestamp = parseFloat(input.timestamp);
const date = new Date(timestamp * 1000);

const formattedTime = date.toLocaleString('en-US', {
  timeZone: 'UTC',
  year: 'numeric',
  month: 'short',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
});

return {
  ...input,
  formattedTimestamp: formattedTime,
  originalTimestamp: timestamp
};

